// Location data for each pool — neighborhood, coordinates, nearest subway —
// merged onto the scraped pools at build time.
//
// The data lives in data/pool_meta.json, keyed by pool_code and generated by
// scripts/make_pool_meta.py, then reviewed by hand. It stays out of
// scraper.py on purpose: a pool doesn't move, and a second source on the daily
// scrape path could break the schedule refresh (HANDOFF.md, "Step 4").
//
// Shared by App.jsx, the SEO fallback and the pool pages, so all three say the
// same thing about where a pool is — the fallback-parity invariant again.

import POOL_META from '../data/pool_meta.json'
import { getBorough } from './utils.js'

// Past this, "nearest subway" is not a walk anyone would plan around; say so
// instead of implying the station is a reasonable way in.
const FAR_SUBWAY_MILES = 1

export const formatMiles = (miles) => `${miles.toFixed(1)} mi`

// "1 Av (L)" — the routes in the MTA's order.
export function stationLabel(s) {
  return `${s.station} (${s.routes.join(', ')})`
}

// "M34+" is the MTA's GTFS name for Select Bus Service; riders know it as SBS.
export const busLabel = (route) => route.replace(/\+$/, ' SBS')

export function busList(place) {
  return (place?.buses ?? []).map(busLabel).join(', ')
}

// The radius the bus list was drawn from (see make_pool_meta.py): a few blocks
// normally, about a 10-minute walk where nothing stops closer.
export function busReach(place) {
  return place?.bus_miles > 0.25 ? 'within about a 10-minute walk' : 'within a few blocks'
}

export function isFarFromSubway(place) {
  const first = place?.subway?.[0]
  return Boolean(first && first.miles > FAR_SUBWAY_MILES)
}

// The one-line summary the card and fallback show; the pool page lists all
// the stations and buses. Where the subway is out of reach (Roy Wilkins), the
// LIRR and buses are how people actually get there, so they lead instead.
export function transitSummary(place) {
  const [first, second] = place?.subway ?? []
  if (!first) return null
  if (first.miles > FAR_SUBWAY_MILES) {
    const ways = [
      place.lirr && `LIRR ${place.lirr.station}, ${formatMiles(place.lirr.miles)}`,
      place.buses?.length && `buses ${busList(place)}`,
    ].filter(Boolean)
    return ways.length
      ? `No subway nearby — ${ways.join('; ')}`
      : `No subway nearby — the closest is ${stationLabel(first)}, ${formatMiles(first.miles)} away`
  }
  const near = [first, second].filter((s) => s && s.miles <= FAR_SUBWAY_MILES)
  return `Nearest subway: ${near.map((s) => `${stationLabel(s)}, ${formatMiles(s.miles)}`).join('; ')}`
}

// Adds `place` to each pool and fills `location.nearest_subway`, which
// PoolCard already renders. Never overwrites a value the scraper supplied.
export function withPoolMeta(pools) {
  return pools.map((pool) => {
    const place = POOL_META[pool.pool_code]
    if (!place) return pool
    return {
      ...pool,
      place,
      location: {
        ...pool.location,
        nearest_subway: pool.location?.nearest_subway ?? transitSummary(place),
      },
    }
  })
}

const squash = (s) => String(s ?? '').toLowerCase().replace(/[^a-z]/g, '')

// "Kips Bay, Manhattan" — or just the borough when the neighborhood is unknown.
// With `skipIfNamed`, also just the borough when the pool's own name already
// says the neighborhood, so a title reads "Chelsea Pool, Manhattan" rather
// than "Chelsea Pool, Chelsea, Manhattan".
export function placeLabel(pool, { skipIfNamed = false } = {}) {
  const borough = getBorough(pool)
  const hood = pool.place?.neighborhood
  if (!hood) return borough
  if (skipIfNamed && squash(pool.pool_name).includes(squash(hood))) return borough
  return `${hood}, ${borough}`
}

// Straight-line miles between two pools, or null without coordinates.
export function milesBetween(a, b) {
  if (!a.place || !b.place) return null
  const rad = (d) => (d * Math.PI) / 180
  const dLat = rad(b.place.lat - a.place.lat)
  const dLng = rad(b.place.lng - a.place.lng)
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(rad(a.place.lat)) * Math.cos(rad(b.place.lat)) * Math.sin(dLng / 2) ** 2
  return 2 * 3958.8 * Math.asin(Math.sqrt(h))
}

// The other pools, nearest first: every pool in the same borough, then the
// closest few elsewhere, so a pool alone in its borough (St. Mary's) still
// links somewhere useful.
export function nearbyPools(pool, pools, { otherBoroughs = 3 } = {}) {
  const borough = getBorough(pool)
  const ranked = pools
    .filter((p) => p.pool_name !== pool.pool_name)
    .map((p) => ({ pool: p, miles: milesBetween(pool, p) }))
    .sort((a, b) => (a.miles ?? Infinity) - (b.miles ?? Infinity))
  return {
    sameBorough: ranked.filter((r) => getBorough(r.pool) === borough),
    otherBoroughs: ranked.filter((r) => getBorough(r.pool) !== borough).slice(0, otherBoroughs),
  }
}
